{"code": "async (page) => {
    const frame = page.frameLocator('iframe').first();
    let fullText = '';
    // Get total pages
    const pageCountText = await frame.locator('.page-count').innerText();
    console.log('pageCountText:', pageCountText);
    // Actually the page count is in a spinbutton? Let's find the element with "of 14"
    const pageInfo = await frame.locator('text=of 14').innerText();
    console.log('pageInfo:', pageInfo);
    // We'll try to extract text from each page by clicking next
    // But we need to ensure we start at page 1
    // Click "Previous" until disabled to go to first page
    const prevButton = frame.locator('button:has-text("Previous")');
    const nextButton = frame.locator('button:has-text("Next")');
    // Go to first page
    while (true) {
        const isDisabled = await prevButton.getAttribute('disabled');
        if (isDisabled) break;
        await prevButton.click();
        await page.waitForTimeout(200);
    }
    // Now iterate through pages
    for (let i = 0; i < 14; i++) {
        // Get text of current page
        const text = await frame.locator('body').innerText();
        fullText += '\n--- Page ' + (i+1) + ' ---\n' + text + '\n';
        // Click next if not last page
        if (i < 13) {
            await nextButton.click();
            await page.waitForTimeout(500); // wait for page render
        }
    }
    return fullText;
}"}

